import { glob, readFile, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import { compileTokens } from "../src/main/document/tokens.ts";

const source = new URL("../src/renderer/design.tokens.json", import.meta.url);
const output = new URL("../../../packages/ui/theme.tokens.css", import.meta.url);
const { css, rows } = await compileTokens(await readFile(source, "utf8"));
const generated =
  "/* Generated by pnpm theme:build. Edit the EasyProtoMocks desktop group. */\n" + css;
const names = new Set(rows.map(({ cssName }) => cssName));
const root = new URL("../../../", import.meta.url);
for await (const path of glob(
  [
    "packages/ui/*.css",
    "packages/ui/components/**/*.css",
    "apps/desktop/src/renderer/**/*.css",
    "apps/web/src/**/*.css",
  ],
  { cwd: fileURLToPath(root), exclude: ["packages/ui/theme.tokens.css"] },
)) {
  const styles = await readFile(new URL(path, root), "utf8");
  for (const [, name] of styles.matchAll(/var\((--ep-desktop-[\w-]+)/g)) {
    if (!names.has(name)) throw new Error(`${path}: missing desktop design token ${name}`);
  }
}

if (process.argv.includes("--check")) {
  if ((await readFile(output, "utf8")) !== generated)
    throw new Error("Shared theme is out of date. Run pnpm theme:build.");
} else {
  await writeFile(output, generated);
}
